-- Credits as the registrar prints them, where the catalogue had another number.
UPDATE courses SET credits = (SELECT o.credits FROM term_offerings o WHERE o.term_id = '2/69' AND o.course_code = courses.code)
WHERE code IN (SELECT o.course_code FROM term_offerings o WHERE o.term_id = '2/69' AND o.credits <> courses.credits);

-- Rebuild the timetable and exams of this term for the courses in the catalogue.
-- (The same statements are in server/src/termSchedule.ts, which the seed runs again after it adds courses.)
DELETE FROM class_sessions WHERE term_id = '2/69';
DELETE FROM exams WHERE term_id = '2/69';
INSERT INTO class_sessions (course_code, term_id, weekday, start_time, end_time, room, instructor, kind)
SELECT o.course_code, o.term_id, json_extract(s.value, '$.weekday'), json_extract(s.value, '$.start'), json_extract(s.value, '$.end'),
       NULLIF(json_extract(s.value, '$.room'), ''), o.teachers, NULLIF(json_extract(s.value, '$.kind'), '')
FROM term_offerings o, json_each(o.sessions) s
WHERE o.term_id = '2/69' AND json_extract(s.value, '$.weekday') IS NOT NULL AND o.course_code IN (SELECT code FROM courses)
ORDER BY o.term_id, o.course_code, s.key;
INSERT INTO exams (course_code, term_id, datetime_start, datetime_end, slot, location)
SELECT course_code, term_id,
       exam_date || CASE exam_slot WHEN 'A' THEN 'T09:30:00+07:00' ELSE 'T14:00:00+07:00' END,
       exam_date || CASE exam_slot WHEN 'A' THEN 'T12:00:00+07:00' ELSE 'T16:30:00+07:00' END,
       exam_slot, NULL
FROM term_offerings
WHERE term_id = '2/69' AND exam_date IS NOT NULL AND course_code IN (SELECT code FROM courses)
ORDER BY term_id, course_code;
